import json
from pathlib import Path
base=Path('research/information-theory-planning')
P=json.loads((base/'pages.json').read_text()); J=json.loads((base/'proposed-items.json').read_text()); items=J['items']; index={x['id']:x for x in items}
new=[]
def item(id,kind,page,deps,statement,proof,locator):
 x=dict(id=id,kind=kind,page=page,deps=deps,statement_or_definition=statement,proof_obligations=[proof],sources=[{'url':'https://ee.stanford.edu/~gray/SourceCoding.pdf','locator':locator}],existing_supplier_checks=['Independent local proof is transcribed in proof-developments.md; existing finite probability, real calculus and linear algebra are used only in their stated scope.'],unresolved_obligations=[],audit_status='independent-scaffold-proof-developed-production-not-authored')
 new.append(x);return x
q='finite-quantization-lloyd-and-compact-companders';qb=q+'-examples';v='finite-trellis-viterbi-and-sequence-decoding';vb=v+'-examples';lz='stationary-ergodic-sources-and-universal-coding'
item('def-it-finite-squared-error-quantizer','definition',q,['def-it-single-letter-distortion-and-block-distortion'],'For a Borel law on R^d with finite second moment and k>=1 centers, assign each point to its nearest squared-distance center, resolving ties by smallest index. The resulting Borel cells define a finite quantizer and finite expected distortion.','Write each cell as finitely many strict/nonstrict distance inequalities and bound distortion by 2E||X||²+2max_j||c_j||².','Independent finite quantizer development; Gray source coding quantization context')
item('lem-it-weighted-centroid-squared-error-identity','lemma',q,['def-it-finite-squared-error-quantizer'],'For positive finite weights summing to one and a nonempty cluster S, its weighted centroid uniquely minimizes cluster squared error; the exact excess is W_S||c-mu_S||². Empty clusters have zero cost for every center.','Expand the squared norm and use the vanishing weighted centered sum.','Local variance decomposition')
item('alg-it-finite-data-lloyd-quantizer','algorithm',q,['lem-it-weighted-centroid-squared-error-identity'],'For N>=1 weighted points and k>=1 initial centers use exact nearest assignments with smallest-index ties, replace each nonempty cluster by its weighted centroid, leave empty centers unchanged, and stop when centers are unchanged.','Specify exact comparison/arithmetic or rational implementation; each finite assignment/update is well defined, including duplicate centers and empty clusters.','Local exact Lloyd procedure')
item('thm-it-finite-data-lloyd-termination-and-fixed-point','theorem',q,['alg-it-finite-data-lloyd-quantizer'],'The stated exact finite-data Lloyd procedure terminates in finitely many steps at a nearest-assignment/centroid fixed point. Any changing iteration strictly decreases distortion; at most 2^(Nk) center configurations are possible. No global-optimum claim follows.','Use strict centroid excess for every changed nonempty center and nonincrease upon reassignment. Each center is its initial value or one of 2^N-1 subset centroids; strict descent forbids repetition.','Local finite-state strict-descent proof')
item('alg-it-exhaustive-global-empirical-quantizer','algorithm',q,['lem-it-weighted-centroid-squared-error-identity'],'Enumerate all k^N assignments, use weighted centroids on nonempty clusters and x_1 on empty clusters, and choose the first minimal exact cost. Return nearest-center reassignment.','Finite enumeration terminates; centroid replacement and nearest reassignment show its cost is no larger than any competing tuple, hence attains the global empirical optimum. O(k^N(N+k)d) exact arithmetic work, no polynomial claim.','Local exhaustive finite optimization proof')
item('def-it-compact-one-dimensional-compander','definition',q,['def-it-finite-squared-error-quantizer'],'Let f,g be positive C1 densities on [a,b], a<b. Set G(x)=integral_a^x g and phi=G^-1. Use boundaries phi(j/N) and reproductions phi((j-1/2)/N), half-open cells except final right endpoint.','Positivity/compactness make G a strictly increasing bijection with C2 inverse; all cells and reproduction points exist, with no source mass outside [a,b].','Local restricted compact compander definition')
item('thm-it-compact-compander-high-rate-distortion','theorem',q,['def-it-compact-one-dimensional-compander'],'For the stated positive C1 compact one-dimensional densities, N²D_N -> (1/12)integral_a^b f/g².','Change variable u=G(x); uniform Taylor remainder for phi and f(phi)/g(phi) gives midpoint-cell leading term F(v)phi\u2032(v)²/(12N³) and O(N^-4). Sum and apply the midpoint Riemann limit.','Local uniform Taylor/Riemann proof')
item('thm-it-optimal-compact-compander-density','theorem',q,['thm-it-compact-compander-high-rate-distortion'],'Within the positive normalized C1 compact compander class, g*=f^(1/3)/integral f^(1/3) minimizes the asymptotic coefficient, with minimum (1/12)(integral f^(1/3))³.','Apply Holder with exponents 3 and 3/2 to (f/g²)^(1/3)g^(2/3), checking equality and admissibility. This is not unrestricted vector quantizer optimality.','Local Holder proof')
item('cex-it-lloyd-fixed-point-need-not-be-global','counterexample',qb,['thm-it-finite-data-lloyd-termination-and-fixed-point'],'Equal weights on {0,1,4,5,9} and centers (5/2,9) give a strict-assignment Lloyd fixed point with distortion 17/5; centers (1/2,6) give 29/10<17/5.','Compute both partitions, exact weighted costs and centroids; every nearest comparison is strict.','Local complete five-point counterexample')
item('ex-it-uniform-compact-compander','example',qb,['thm-it-compact-compander-high-rate-distortion'],'For uniform density on [0,1] and g=1, midpoint quantization has exact distortion 1/(12N²), agreeing with the compander limit.','Integrate squared distance over N equal symmetric cells.','Local exact integral')
item('def-it-finite-layered-trellis-path-problem','definition',v,[],'A finite ordered layered graph S_0,...,S_N, N>=0, has finite edge lists from layer t-1 to t, initial costs in R union {+infinity}, edge costs in that set, and a terminal subset. A feasible path has finite total cost and ends at a terminal. Min empty is +infinity; minus infinity is excluded.','Finite path set makes every finite optimum attained; empty layers/terminals and N=0 remain legal.','Local finite graph definition')
item('alg-it-viterbi-finite-trellis','algorithm',v,['def-it-finite-layered-trellis-path-problem'],'Set delta_0=a. In layer t minimize delta_(t-1)(u)+c(e) over incoming edges, recording the first finite minimizing edge. Choose the first finite minimum terminal and backtrack; otherwise return no finite feasible path.','Fixed orders determine ties, infinity propagates unambiguously and only finite minima receive predecessors.','Local finite dynamic programming procedure')
item('thm-it-viterbi-termination-and-optimality','theorem',v,['alg-it-viterbi-finite-trellis'],'Viterbi terminates and returns a minimum-cost feasible path or correctly reports none. It uses O(sum|S_t|+sum|E_t|) exact additions/comparisons, two adjacent cost arrays and O(sum|S_t|) predecessor storage.','Induct on layers: every path is a predecessor path followed by an incoming edge. Finite attained minima have backpointers; layer order excludes cycles even with negative finite costs. N=0 is direct terminal minimization.','Local induction and resource count')
item('def-it-finite-hidden-markov-sequence-map','definition',v,['def-it-finite-layered-trellis-path-problem'],'For finite states, initial pmf pi, stochastic transitions A_t and finite observation emissions b_(t,s), a path has joint weight pi(s_0) product_t A_t(s_(t-1),s_t)b_(t,s_t)(y_t). Posterior sequence MAP is defined only when the finite evidence sum is positive.','Finite products/sums define the joint law and evidence; zero evidence is excluded from posterior conditioning.','Local finite HMM model')
item('thm-it-viterbi-hidden-markov-sequence-map','theorem',v,['def-it-finite-hidden-markov-sequence-map','thm-it-viterbi-termination-and-optimality'],'Use initial costs -ln pi and edge costs -ln A_t-ln b_(t,s)(y_t), zero factors giving +infinity. Positive evidence makes Viterbi a posterior sequence-MAP decoder; zero evidence gives no positive-probability path.','Finite product logarithm turns joint maximization into additive minimization; dividing by positive common evidence preserves order.','Local exact HMM reduction')
item('cex-it-marginal-map-concatenation-can-be-impossible','counterexample',vb,['thm-it-viterbi-hidden-markov-sequence-map'],'Initial probabilities (.4,.3,.3), transition rows (0,.5,.5),(1,0,0),(1,0,0), and uninformative observations have coordinate marginal modes (1,1), an impossible path. Sequence MAP is (2,1) or (3,1), each probability .3.','Compute next marginal (.6,.2,.2) and all six positive/zero transition path weights.','Local exact counterexample')
item('ex-it-viterbi-unreachable-terminal','example',vb,['thm-it-viterbi-termination-and-optimality'],'A two-layer trellis with no edge to its sole terminal correctly returns no finite feasible path; an infinite minimum has no stored predecessor.','Compute the empty incoming minimum and terminal infinity, including failure rather than undefined backtracking.','Local boundary example')
item('alg-it-finite-window-lz77-code','algorithm',lz,['def-it-finite-source-code'],'Input finite x in A^n, known n>=0, window w>=1, fresh EOS. At each start choose maximal overlapping previous-offset match of length ell<=remaining-1 (smallest offset tie); emit (offset,ell,next literal), advancing ell+1 through final literal EOS. Use offset zero iff ell zero.','Offsets, lengths and literals have fixed fields ceil(log2(w+1)), ceil(log2(n+1)), ceil(log2(|A|+1)); decoder copies one symbol at a time from its growing prefix, validates fields and exact n-symbol EOS boundary. Full procedure in canonical development.','Independent finite-window procedure; asymptotic Kontoyiannis match statistic kept distinct')
item('thm-it-finite-window-lz77-correctness-and-termination','theorem',lz,['alg-it-finite-window-lz77-code'],'The specified finite-window LZ77 encoder terminates in <=n+1 tokens and its framed overlapping-copy decoder reconstructs x exactly. No recurrence-rate or universality claim follows from this particular fixed-width framing.','Each token consumes >=1 symbol. For overlapping copies the source index is strictly earlier than its destination, so token induction plus within-token induction proves exact reconstruction.','Local complete finite overlap induction')
item('lem-it-path-connected-finite-support-reduction','lemma','multiuser-channel-networks',[],'For a nonempty path-connected S subset R^d, d>=1, every x in conv S is a convex combination of <=d points of S.','Reduce by affine dependence to d+1 points. Translate x=0 interior simplex. A path from v0 inside cone{-sum a_i v_i:a_i>=0} to v1 outside first meets its boundary; there a cone coordinate vanishes, yielding a combination with <=d points.','Local moving-simplex proof, no external Fenchel-Eggleston assumption')
# Pair registration.
for label,page,title,req,summary in [('IT23',q,'Finite Quantization, Lloyd Iteration, and Compact Companders',['rate-distortion-and-lossy-source-coding'], 'Finite empirical optimization and restricted compact one-dimensional high-rate asymptotics with exact algorithm contracts.'),('IT24',v,'Finite Trellises, Viterbi, and Sequence Decoding',['prefix-codes-and-finite-lossless-coding'], 'Finite layered dynamic programming and exact HMM sequence MAP, with unreachable-state and zero-evidence boundaries.')]:
 for kind,pg,comp in [('A',page,page+'-examples'),('B',page+'-examples',page)]:
  P['pages'].append(dict(label=label+('-B' if kind=='B' else ''),page=pg,title=title+(' — Examples' if kind=='B' else ''),kind=kind,category='information-theory',requires=req if kind=='A' else [page],companion=comp,items=[x['id'] for x in new if x['page']==pg],summary=summary if kind=='A' else 'Worked exact computations and counterexamples; no later A-page prerequisite.'))
for x in new:
 if x['id'] in index: raise ValueError(x['id'])
 items.append(x)
 for page in P['pages']:
  if page['page']==x['page'] and x['id'] not in page['items']:page['items'].append(x['id'])
# Exact definition repairs.
i=index['def-it-renyi-divergence-finite'];i['statement_or_definition']+=' For every alpha>0 each term with p_i=0 is defined as zero, including p_i=q_i=0.'
i=index['thm-it-renyi-to-kl-limit'];i['statement_or_definition']=i['statement_or_definition'].replace('the limit is finite or infinite KL according to its finite sum','the limit is its finite KL sum')
i=index['def-it-von-neumann-entropy'];i['statement_or_definition']='For a state rho on a nonzero finite-dimensional Hilbert space, S(rho)=-Tr rho ln rho by spectral calculus, with 0 ln 0=0. The default unit is nats; base-2 entropy is S/ln 2.'
i=index['def-it-finite-dimensional-quantum-relative-entropy'];i['statement_or_definition']+=' Logarithms are natural; a base-2 divergence divides this value by ln 2.'
i=index['def-it-lz77-overlapping-window-match-length'];i['unresolved_obligations']=[];i['audit_status']='independent-scaffold-definition-checked-production-not-authored'
i['existing_supplier_checks']=['The extended-valued recurrence statistic is separate from alg-it-finite-window-lz77-code; the latter proves finite framing/termination but no automatic asymptotic-rate equivalence.']
# Completed local proof != production carrier minting.
for id in ['thm-it-normal-approximation-nondegenerate-dmc','lem-it-dmc-capacity-output-saddlepoint','lem-it-dmc-caid-conditional-variance-identity','thm-it-dmc-uniform-quadratic-capacity-decay']:
 if id in index:index[id]['unresolved_obligations']=[];index[id]['audit_status']='independent-scaffold-proof-developed-production-not-authored'
# Quantum continuity exact existing supports and conditional bound.
for id in ['lem-it-finite-quantum-entropy-continuity','lem-it-finite-quantum-conditional-entropy-continuity']:
 i=index[id]
 for dep in ['thm-qc-purification-existence-and-unitary-equivalence','thm-qc-schmidt-decomposition']:
  if dep not in i['deps']:i['deps'].append(dep)
 i['unresolved_obligations']=[];i['audit_status']='independent-scaffold-proof-developed-production-not-authored'
(base/'pages.json').write_text(json.dumps(P,ensure_ascii=False,indent=2)+'\n');(base/'proposed-items.json').write_text(json.dumps(J,ensure_ascii=False,indent=2)+'\n')
# Canonical transcription of actual proofs (source evidence stays lane-owned).
with (base/'proof-developments.md').open('a') as f:
 for title,name in [('Independent finite quantization and trellis developments','quantization-and-viterbi-proof.md'),('Finite-window LZ77 procedure, correctness and framing','lz77-finite-procedure.md'),('Path-connected finite support reduction','path-connected-support-reduction.md'),('Finite quantum mixing and continuity details','quantum-continuity-supplier-details.md')]:
  text=(base/'audit'/name).read_text();f.write('\n\n## '+title+'\n\n'+text.split('\n',1)[1])
# Small existing canonical text repairs.
p=base/'definition-justifications.md';text=p.read_text().replace('S(ρ)=-Tr ρ log_2ρ','S(ρ)=-Tr ρ lnρ (nats; divide by ln 2 for bits)')
text=text.replace('`alg-it-lz78-universal-code` and `def-it-lz77-overlapping-window-match-length` require their exact\ndictionary initialization, ordered finite alphabet, phrase parsing, integer\nindex representation, EOF symbol/termination rule, and actual output-length\naccounting.', '`alg-it-lz78-universal-code` and `alg-it-finite-window-lz77-code` specify their exact dictionary/window initialization, ordered finite alphabet, finite parsing, index representation, EOS termination, and framed output accounting. The separate `def-it-lz77-overlapping-window-match-length` is an extended-valued bi-infinite statistic and has no bitstream procedure claim.')
text=text.replace('Stop only when\n`max_j c_j(q)-1≤ε`.', 'Stop only when\n`ln(max(1,max_j c_j(q)))≤ε`, the certified Lagrangian gap.')
text+='\n\n## Finite quantization and trellis definitions (IT23–IT24)\n\nThe finite quantizer uses measurable nearest-center cells with fixed ties and a finite second moment. Exact empirical Lloyd iteration uses positive finite weights, unchanged empty centers and exact comparisons; its finite termination does not imply global optimality. The separate exponential enumeration attains a global empirical optimum. Compact companders require positive C1 source and point densities on a fixed finite interval, so inverse derivatives and uniform Taylor constants exist and overload is absent. Finite trellises explicitly allow unreachable states, empty terminal sets, parallel edges, N=0 and negative finite edge costs; infinity is propagated but never subtracted. HMM posterior sequence MAP requires positive evidence. Full local procedures, correctness, termination, resource counts and counterexamples are transcribed in proof-developments.md.\n'
p.write_text(text)
p=base/'proof-developments.md';text=p.read_text().replace('In an optimal full binary tree two deepest leaves are\nsiblings;', 'For positive support size m>=2, prune unused leaves and contract unary nodes of any finite prefix tree without increasing cost. Every full tree has exactly 2m-1 vertices, so there are finitely many ordered shapes and labelings and an optimal full tree exists. In such a tree two deepest leaves are siblings;');p.write_text(text)
print({'added_items':len(new),'pages':len(P['pages']),'proposals':len(items)})
